using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using NUnit.Framework;

namespace Bugsee.WrapperPolicy.Tests
{
    /// <summary>
    /// Links the managed Android bridge to the Android SDK it is pinned to. Unity resolves every
    /// AndroidJavaClass / AndroidJavaObject call by name and signature at run time, so a renamed or re-shaped SDK
    /// method is otherwise a device-only failure. The SDK side is a committed snapshot
    /// (Fixtures/android-sdk-api/&lt;version&gt;.txt, javap of the pinned AARs, regenerated by
    /// Tools~/scripts/update-android-api-manifest.sh), so the check runs without the SDK or a network.
    ///
    /// Checked, for every CallStatic on a com.bugsee.library class: a public static method of that name whose
    /// parameter list takes the arguments (count, and the type of each argument where the text tells it: literals and
    /// casts, and variables, parameters and helper calls through their declared C# type; an AndroidJavaProxy
    /// subclass through the interface it names in base("...")) and whose return type fits the call (plain
    /// CallStatic = void, CallStatic&lt;bool|int|long|float|double|string&gt; = that primitive or String,
    /// CallStatic&lt;AndroidJavaObject&gt; = any reference). Also: every com.bugsee.library class named in the C# is in the
    /// snapshot, every AndroidJavaProxy subclass names a snapshot (or JDK) interface and each lower-camel method it
    /// defines is one of that interface's with a void return and parameter types the Java ones can bind to, and every
    /// instance Call/Set names a method that exists with that arity (and a compatible return type) on the receiver's
    /// contract inside the wrapper classes listed in ReceiverContracts (event, breadcrumb, span, report, attachment),
    /// elsewhere in any SDK contract, or in a short JDK list.
    ///
    /// The raw AndroidJNI lookups of Runtime/Capture/BugseeFrameCapturer.cs (GetMethodID / GetStaticMethodID /
    /// GetStaticFieldID, with JNI descriptors) are checked for exact name, parameter and return types, and for fields the
    /// name, type and staticness.
    /// The one class it uses outside the snapshot (internal TimeUtils) is listed in RawJniNotInSnapshot.
    ///
    /// Static field reads (GetStatic) on an SDK class are checked by name and type (a computed name only in
    /// ComputedStaticFieldReaders: AndroidSpanHandle, whose SpanStatus constants Every_SpanStatus_constant_... covers), and so is
    /// every enum name passed to an SDK enum's valueOf (the C# enum's members, or the literals assigned to the variable).
    ///
    /// The typed half lives in AndroidSdkBindingTypesTests.cs. An argument's type comes from the text (literals, operators,
    /// conditionals, casts that cover the whole expression, declarations, initialisers, helper methods in any Android
    /// source, members of the runtime's own classes) or, for an AndroidJavaObject, from the Java class it is (a CallStatic /
    /// GetStatic / Call return type in the snapshot, a constructor, EnumFromInt, a conditional of those, the native object
    /// of a wrapper). Every CallStatic argument and every argument of an instance Call on a resolved receiver must be typed
    /// and bind to the Java parameter (a C# enum never does: it has no JNI signature), and the return type must fit.
    /// Arguments that stay "some Java object" (a View, an Activity, a callback handed in by the SDK) are counted and held
    /// to the named LooseObjectArguments; receivers that are not resolved to a snapshot class are held to the exact
    /// UnresolvedReceivers, so a renamed wrapper field cannot silently drop its calls. The Java side of UnityWrapper
    /// (Plugins/Android/*.java) is parsed into the same model: C# calls and `new AndroidJavaObject("com.bugsee...")` on it
    /// are checked like SDK calls, its @Override methods against the SDK types it extends, and its calls into the SDK
    /// (static, on typed variables, constants, imports) and com.bugsee.library string literals (the reflective extension
    /// lookups) against the snapshot.
    ///
    /// Limits (a test-only best effort, deliberately not a C# or Java compiler): an instance Call on an unresolved receiver
    /// (JDK objects, `Ext()`, a contract passed in) is matched by name and arity against every SDK class, or the short JDK
    /// list; a local is typed from its last textual declaration before the use, ignoring scope; `a.b.Name` is typed from
    /// any uniquely named member of the runtime sources; `T?` is typed as T; ContractFields and InstanceHelpers are
    /// hard-coded names; generic parameters are compared by their erased type and varargs by their element type; a Java
    /// argument other than a literal, a primitive cast or a local with a declared type is not typed; for a reflective {class, method} pair only the
    /// method name is checked, and a class of an AAR outside the snapshot (ExtensionClassesNotInSnapshot) not at all;
    /// helper-method return types are followed through `return` statements only.
    ///
    /// Overlaps: CI compiles Plugins/Android against the real SDK (Tests~/Android/wrapper, a JUnit build), which catches
    /// every Java-side mismatch a javac would; the Java-side checks here exist to fail in seconds, offline, with the
    /// snapshot. NativeBindingTests keeps its older arity-only checks of the UnityWrapper statics and constructor.
    /// </summary>
    public partial class AndroidSdkBindingTests
    {
        static string RepoFile(string relative)
        {
            var dir = TestContext.CurrentContext.TestDirectory;
            while (!string.IsNullOrEmpty(dir))
            {
                if (File.Exists(Path.Combine(dir, "package.json")))
                    return Path.Combine(dir, relative);
                dir = Directory.GetParent(dir)?.FullName;
            }

            throw new InvalidOperationException("Could not locate repo root (package.json).");
        }

        static string StripComments(string s)
        {
            s = Regex.Replace(s, @"/\*.*?\*/", " ", RegexOptions.Singleline);
            return Regex.Replace(s, @"(?<![:""])//[^\n]*", " ");
        }

        sealed class JavaMethod
        {
            public string Name;
            public bool Static;
            public bool Abstract;
            public string Ret; // erased; null for a constructor
            public string[] Params; // erased
            public bool VarArgs;
            public bool Public = true; // false for a protected snapshot member; a Java source member: its `public` modifier
            public bool Override; // a Java source method marked @Override

            public override string ToString() =>
                (Static ? "static " : "") + Ret + " " + Name + "(" + string.Join(", ", Params) + ")";
        }

        sealed class JavaClass
        {
            public string Name;
            public bool IsEnum;
            public Dictionary<string, (string type, bool isStatic)> Fields = new Dictionary<string, (string, bool)>();
            public List<string> Supers = new List<string>(); // extended / implemented types, erased
            public List<JavaMethod> Methods = new List<JavaMethod>();
        }

        /// <summary>A java type without its generic arguments.</summary>
        static string Erase(string type)
        {
            string previous;
            do
            {
                previous = type;
                type = Regex.Replace(type, "<[^<>]*>", "");
            } while (type != previous);

            return type.Trim();
        }

        static readonly HashSet<string> JavaPrimitives = new HashSet<string>
            { "boolean", "byte", "short", "char", "int", "long", "float", "double" };

        static bool IsReference(string javaType) => javaType != "void" && !JavaPrimitives.Contains(javaType);

        static string[] SplitParams(string args)
        {
            var parts = new List<string>();
            int depth = 0, start = 0;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i] == '<') depth++;
                else if (args[i] == '>') depth--;
                else if (args[i] == ',' && depth == 0)
                {
                    parts.Add(args.Substring(start, i - start).Trim());
                    start = i + 1;
                }
            }

            var last = args.Substring(start).Trim();
            if (last.Length > 0) parts.Add(last);
            return parts.ToArray();
        }

        static Dictionary<string, JavaClass> _manifest;

        static string ManifestFile()
        {
            var version = Regex.Match(File.ReadAllText(RepoFile("Tools~/versions.env")), "ANDROID_SDK_VERSION=\"([^\"]+)\"").Groups[1].Value;
            Assert.That(version, Is.Not.Empty);
            var path = RepoFile("Tests~/WrapperPolicy/Fixtures/android-sdk-api/" + version + ".txt");
            Assert.That(File.Exists(path), Is.True,
                "No Android API snapshot for the pinned SDK " + version + ". Run Tools~/scripts/update-android-api-manifest.sh.");
            Assert.That(Directory.GetFiles(Path.GetDirectoryName(path), "*.txt").Length, Is.EqualTo(1),
                "Only the snapshot of the pinned SDK is kept; rerun Tools~/scripts/update-android-api-manifest.sh.");
            return path;
        }

        static Dictionary<string, JavaClass> Manifest()
        {
            if (_manifest != null) return _manifest;
            var classes = new Dictionary<string, JavaClass>();
            JavaClass current = null;
            foreach (var raw in File.ReadAllLines(ManifestFile()))
            {
                if (raw.StartsWith("#") || raw.Trim().Length == 0 || raw.Trim() == "}") continue;
                if (!raw.StartsWith(" "))
                {
                    // "$" is part of a nested class name (Bugsee$Companion).
                    var header = Regex.Match(raw, @"\b(class|interface|enum)\s+([\w.$]+)");
                    Assert.That(header.Success, Is.True, "Unparsed snapshot line: " + raw);
                    current = new JavaClass { Name = header.Groups[2].Value, IsEnum = header.Groups[1].Value == "enum" || raw.Contains("extends java.lang.Enum<") };
                    foreach (Match x in Regex.Matches(Erase(raw), @"\b(?:extends|implements)\s+([\w.$,\s]+?)(?=\s+implements\b|\s*\{|$)"))
                        current.Supers.AddRange(x.Groups[1].Value.Split(',').Select(t => t.Trim()).Where(t => t.Length > 0));
                    classes[current.Name] = current;
                    continue;
                }

                var open = raw.IndexOf('(');
                if (open < 0)
                {
                    var words = Erase(raw).Trim().TrimEnd(';').Split(' ', StringSplitOptions.RemoveEmptyEntries);
                    current.Fields[words[words.Length - 1]] = (words[words.Length - 2], words.Contains("static"));
                    continue;
                }

                var close = raw.LastIndexOf(')');
                var head = raw.Substring(0, open).Trim();
                var name = head.Substring(head.LastIndexOfAny(new[] { ' ', '>' }) + 1);
                var args = SplitParams(raw.Substring(open + 1, close - open - 1));
                // Return type: what is left of the head without the modifiers, the method's own <T> and the name.
                var ret = Regex.Replace(head.Substring(0, head.Length - name.Length), @"\b(public|protected|static|final|abstract|synchronized|native|default)\b", " ");
                ret = Regex.Replace(ret, @"^\s*<[^>]*>", "").Trim();
                current.Methods.Add(new JavaMethod
                {
                    Name = name,
                    Static = Regex.IsMatch(head, @"\bstatic\b"),
                    Public = !Regex.IsMatch(head, @"\bprotected\b"),
                    Abstract = Regex.IsMatch(head, @"\babstract\b"),
                    Ret = ret.Length == 0 ? null : Erase(ret),
                    Params = args.Select(a => Erase(a.Replace("...", ""))).ToArray(),
                    VarArgs = args.Length > 0 && args[args.Length - 1].EndsWith("..."),
                });
            }

            return _manifest = classes;
        }

