        static IEnumerable<string> AndroidSources() =>
            Directory.GetFiles(RepoFile("Runtime/Platform/Android"), "*.cs", SearchOption.AllDirectories).OrderBy(f => f);

        static string[] SplitArgs(string args)
        {
            var parts = new List<string>();
            int depth = 0, start = 0;
            char quote = '\0';
            for (int i = 0; i < args.Length; i++)
            {
                char c = args[i];
                if (quote != '\0')
                {
                    if (c == '\\') i++;
                    else if (c == quote) quote = '\0';
                    continue;
                }

                if (c == '"' || c == '\'') quote = c;
                else if (c == '(' || c == '[' || c == '{') depth++;
                else if (c == ')' || c == ']' || c == '}') depth--;
                else if (c == ',' && depth == 0)
                {
                    parts.Add(args.Substring(start, i - start).Trim());
                    start = i + 1;
                }
            }

            var last = args.Substring(start).Trim();
            if (last.Length > 0 || parts.Count > 0) parts.Add(last);
            return parts.ToArray();
        }

        static string BalancedArgs(string src, int open)
        {
            int depth = 1, i = open;
            bool inString = false;
            for (; i < src.Length && depth > 0; i++)
            {
                char c = src[i];
                if (inString)
                {
                    if (c == '\\') i++;
                    else if (c == '"') inString = false;
                    continue;
                }

                if (c == '"') inString = true;
                else if (c == '(') depth++;
                else if (c == ')') depth--;
            }

            return src.Substring(open, i - 1 - open);
        }

        static string Resolve(string expr, string src)
        {
            expr = expr.Trim();
            var literal = Regex.Match(expr, "^\"([^\"]*)\"$");
            if (literal.Success) return literal.Groups[1].Value;
            var constant = Regex.Match(src, @"\bconst\s+string\s+" + Regex.Escape(expr) + @"\s*=\s*""([^""]*)""");
            return constant.Success ? constant.Groups[1].Value : null;
        }

        sealed class Binding
        {
            public string Var;
            public int Index;
            public string Class;
        }

        static readonly Regex ClassBindingRe =
            new Regex(@"\b(?:var|AndroidJavaClass)\s+(\w+)\s*=\s*new\s+AndroidJavaClass\(\s*([^)]+?)\s*\)");

        /// <summary>Per file: the locals and fields bound to an AndroidJavaClass, with the class they name.</summary>
        static Dictionary<string, List<Binding>> Bindings(Dictionary<string, string> sources)
        {
            var result = new Dictionary<string, List<Binding>>();
            foreach (var kv in sources)
            {
                var list = new List<Binding>();
                foreach (Match m in ClassBindingRe.Matches(kv.Value))
                {
                    var cls = Resolve(m.Groups[2].Value, kv.Value);
                    // A class taken as a parameter (AndroidOptionsMapper.EnumFromInt) is checked through its callers.
                    if (cls == null) cls = "";
                    Assert.That(cls != "" || m.Groups[2].Value == "className", Is.True, Path.GetFileName(kv.Key) + ": cannot resolve the class of " + m.Value);
                    list.Add(new Binding { Var = m.Groups[1].Value, Index = m.Index, Class = cls });
                }

                result[kv.Key] = list;
            }

            return result;
        }

        static Dictionary<string, string> Sources() =>
            AndroidSources().ToDictionary(f => f, f => StripComments(File.ReadAllText(f)));

        [Test]
        public void The_snapshot_and_the_parsers_see_the_known_surface()
        {
            var manifest = Manifest();
            Assert.That(manifest.Keys, Does.Contain("com.bugsee.library.Bugsee")
                .And.Contain("com.bugsee.library.contracts.options.LogLevel"));
            var bugsee = manifest["com.bugsee.library.Bugsee"];
            Assert.That(bugsee.Methods.Count(m => m.Static && m.Name == "launch"), Is.GreaterThanOrEqualTo(4));
            Assert.That(bugsee.Methods.Where(m => m.Name == "deleteCollectedDataOnDevice").Select(m => m.Params.Length),
                Is.EquivalentTo(new[] { 2, 3 }));
            Assert.That(manifest["com.bugsee.library.contracts.options.IssueSeverity"].IsEnum, Is.True);

            var sources = Sources();
            Assert.That(Calls(sources).Count, Is.GreaterThanOrEqualTo(50));
            Assert.That(Calls(sources).Count(c => c.Class == "com.bugsee.library.Bugsee"), Is.GreaterThanOrEqualTo(40));
        }

        [Test]
        public void Every_com_bugsee_library_class_named_in_managed_code_is_in_the_snapshot()
        {
            var manifest = Manifest();
            var missing = new List<string>();
            var seen = 0;
            foreach (var kv in Sources())
            {
                foreach (Match m in Regex.Matches(kv.Value, @"""(com\.bugsee\.library\.[\w.$]+)"""))
                {
                    seen++;
                    if (!manifest.ContainsKey(m.Groups[1].Value)) missing.Add(Path.GetFileName(kv.Key) + ": " + m.Groups[1].Value);
                }
            }

            Assert.That(seen, Is.GreaterThanOrEqualTo(10));
            Assert.That(missing, Is.Empty, "Classes not in the Android SDK snapshot");
        }

        sealed class StaticCall
        {
            public string File;
            public string Class;
            public string Name;
            public string[] Args;
            public string Generic; // the T of CallStatic<T>; null for the plain (void) form
            public string Src;
            public int Index;
        }

        static List<StaticCall> Calls(Dictionary<string, string> sources)
        {
            var bindings = Bindings(sources);
            // Fields (_bugsee) are bound in one file and used in others: resolve them by name across files.
            var fieldBindings = bindings.Values.SelectMany(b => b).Where(b => b.Var.StartsWith("_"))
                .GroupBy(b => b.Var).ToList();
            foreach (var g in fieldBindings)
                Assert.That(g.Select(b => b.Class).Distinct().Count(), Is.EqualTo(1),
                    "the field '" + g.Key + "' is bound to different classes in different files; resolve it per file: "
                    + string.Join(", ", g.Select(b => b.Class).Distinct()));
            var fieldClass = fieldBindings.ToDictionary(g => g.Key, g => g.First().Class);
            var calls = new List<StaticCall>();
            var callRe = new Regex(@"\b(?:\w+\s*\.\s*)*(\w+)\s*\??\s*\.\s*CallStatic(?:<([^>]+)>)?\s*\(");
            foreach (var kv in sources)
            {
                foreach (Match m in callRe.Matches(kv.Value))
                {
                    var receiver = m.Groups[1].Value;
                    var args = SplitArgs(BalancedArgs(kv.Value, m.Index + m.Length));
                    var file = Path.GetFileName(kv.Key);
                    var prior = bindings[kv.Key].Where(b => b.Var == receiver && b.Index < m.Index).LastOrDefault();
                    string cls = prior?.Class;
                    if (cls == null) fieldClass.TryGetValue(receiver, out cls);
                    if (cls == "") cls = null;
                    var name = Resolve(args[0], kv.Value);
                    // The one hard-coded special case: EnumFromInt takes its class as a parameter: the call is checked through its callers, below.
                    var classAsParameter = cls == null && name == null && Regex.IsMatch(kv.Value,
                        @"static\s+\w+\s+EnumFromInt\(\s*string\s+className\s*,\s*string\s+method\b") && receiver == "clazz";
                    Assert.That(cls != null || classAsParameter, Is.True,
                        file + ": the class of '" + receiver + "' in CallStatic is not bound by a visible 'new AndroidJavaClass(...)'");
                    if (classAsParameter) continue;
                    // A method name chosen at run time cannot be checked here.
                    Assert.That(name, Is.Not.Null, file + ": CallStatic with a computed method name " + args[0]);
                    calls.Add(new StaticCall
                    {
                        File = file, Class = cls, Name = name, Args = args.Skip(1).ToArray(),
                        Generic = m.Groups[2].Success ? m.Groups[2].Value.Trim() : null, Src = kv.Value, Index = m.Index,
                    });
                }

                // EnumFromInt(<class const>, "<method>", value, default) calls <method>(int) and <method>(int, enum) on the class.
                foreach (Match m in Regex.Matches(kv.Value, @"\bEnumFromInt\(\s*(\w+)\s*,\s*""(\w+)""\s*,"))
                {
                    var cls = Resolve(m.Groups[1].Value, kv.Value);
                    Assert.That(cls, Is.Not.Null, Path.GetFileName(kv.Key) + ": EnumFromInt class " + m.Groups[1].Value);
                    var file = Path.GetFileName(kv.Key);
                    calls.Add(new StaticCall { File = file, Class = cls, Name = m.Groups[2].Value, Args = new[] { "(int)0" }, Generic = "AndroidJavaObject", Src = "", Index = 0 });
                    calls.Add(new StaticCall { File = file, Class = cls, Name = m.Groups[2].Value, Args = new[] { "(int)0", "(AndroidJavaObject)null" }, Generic = "AndroidJavaObject", Src = "", Index = 0 });
                }
            }

            return calls;
        }

        // ---- the C# type of an argument expression -> the java parameter types it can bind to --------------------------------

        static readonly HashSet<string> NotATypeWord = new HashSet<string>
            { "return", "else", "case", "throw", "in", "is", "as", "new", "ref", "out", "await", "yield", "goto", "using" };

        sealed class Proxy
        {
            public string Name;
            public string Interface;
            public string Body;
        }

        static string ClassBody(string src, int from)
        {
            int open = src.IndexOf('{', from), depth = 0, i = open;
            for (; i < src.Length; i++)
            {
                if (src[i] == '{') depth++;
                else if (src[i] == '}' && --depth == 0) break;
            }

            return src.Substring(open + 1, i - open - 1);
        }

        static Dictionary<string, Proxy> Proxies(Dictionary<string, string> sources)
        {
            var result = new Dictionary<string, Proxy>();
            foreach (var kv in sources)
            {
                foreach (Match m in Regex.Matches(kv.Value, @"\bclass\s+(\w+)(?:<[^>]*>)?\s*:\s*AndroidJavaProxy\b"))
                {
                    var body = ClassBody(kv.Value, m.Index);
                    var iface = Regex.Match(body, @"\bbase\(\s*""([\w.$]+)""\s*\)");
                    Assert.That(iface.Success, Is.True, m.Groups[1].Value + ": an AndroidJavaProxy subclass without base(\"<interface>\")");
                    result[m.Groups[1].Value] = new Proxy { Name = m.Groups[1].Value, Interface = iface.Groups[1].Value, Body = body };
                }
            }

            return result;
        }

        /// <summary>Return types of the methods declared in the runtime sources, by name (a name with two types is unusable).</summary>
        static Dictionary<string, string> MethodReturnTypes()
        {
            var types = new Dictionary<string, HashSet<string>>();
            var re = new Regex(@"(?:(?:static|public|internal|private|protected|override)\s+)*([\w<>\[\]?.]+)\s+(\w+)\s*\([^)]*\)\s*(?:\{|=>)");
            foreach (var path in Directory.GetFiles(RepoFile("Runtime"), "*.cs", SearchOption.AllDirectories))
            {
                foreach (Match m in re.Matches(StripComments(File.ReadAllText(path))))
                {
                    if (NotATypeWord.Contains(m.Groups[1].Value)) continue;
                    if (!types.TryGetValue(m.Groups[2].Value, out var set)) types[m.Groups[2].Value] = set = new HashSet<string>();
                    set.Add(m.Groups[1].Value);
                }
            }

            return types.Where(t => t.Value.Count == 1).ToDictionary(t => t.Key, t => t.Value.First());
        }

        static bool InterfaceReaches(string iface, string target, Dictionary<string, JavaClass> manifest)
        {
            if (iface == target) return true;
            return manifest.TryGetValue(iface, out var cls) && cls.Supers.Any(s => InterfaceReaches(s, target, manifest));
        }


        /// <summary>Whether the java return type fits what the call asked Unity for (CallStatic: void, CallStatic&lt;T&gt;: T).</summary>
        static bool ReturnFits(JavaMethod method, string generic)
        {
            switch (generic)
            {
                case null: return method.Ret == "void";
                case "bool": return method.Ret == "boolean";
                case "string": return method.Ret == "java.lang.String";
                case "sbyte": return method.Ret == "byte";
                case "int":
                case "long":
                case "float":
                case "double":
                case "short":
                case "char": return method.Ret == generic;
                case "AndroidJavaObject": return IsReference(method.Ret);
                default: return true;
            }
        }

        // The wrapper classes whose native receiver is one SDK contract (any of the listed ones): inside such a class an
        // instance Call must name a method of that contract (or of a type it extends), not just of some class.
        static readonly Dictionary<string, string[]> ReceiverContracts = new Dictionary<string, string[]>
        {
            { "AndroidNetworkEvent", new[] { "exchange.NetworkEvent" } },
            { "AndroidLogEvent", new[] { "exchange.LogEvent" } },
            { "AndroidBreadcrumb", new[] { "exchange.Breadcrumb" } },
            { "AndroidSpanHandle", new[] { "performance.Span", "performance.Transaction" } },
            { "AndroidReport", new[] { "reporting.Report" } },
            { "AndroidManagedReport", new[] { "reporting.Report" } },
            { "AndroidAttachment", new[] { "reporting.Attachment" } },
            { "AndroidManagedAttachment", new[] { "reporting.Attachment" } },
        };

        // JDK calls made on other objects inside a ReceiverContracts class ("file:method"): enum names, map entries, lists and
        // the like, not the contract receiver.
        static readonly HashSet<string> ScopedJdkCalls = new HashSet<string>
        {
            "AndroidExchangeEvents.cs:getValue", "AndroidExchangeEvents.cs:name",
            "AndroidReport.cs:add", "AndroidReport.cs:get", "AndroidReport.cs:getValue", "AndroidReport.cs:size", "AndroidReport.cs:toString",
            "AndroidReport.cs:write", "AndroidReport.cs:flush", "AndroidReport.cs:close",
        };

        static void AddWithSupers(string cls, Dictionary<string, JavaClass> manifest, List<JavaMethod> into, int depth = 0)
        {
            if (depth > 6 || !manifest.TryGetValue(cls, out var jc)) return;
            into.AddRange(jc.Methods.Where(m => !m.Static));
            foreach (var super in jc.Supers) AddWithSupers(super, manifest, into, depth + 1);
            // Every object is a java.lang.Object (the snapshot alone has no JDK classes; FullManifest adds Object).
            if (depth == 0 && manifest.TryGetValue("java.lang.Object", out var obj)) into.AddRange(obj.Methods);
        }

        [Test]
        public void Every_instance_Call_names_a_method_of_its_receiver_contract_or_the_sdk_or_the_jdk_with_that_arity()
        {
            var manifest = Manifest();
            var allSdk = new List<JavaMethod>();
            foreach (var c in manifest.Values) allSdk.AddRange(c.Methods.Where(m => !m.Static));
            var failures = new List<string>();
            var seen = 0;
            var scoped = 0;
            // Call("name", ...), Call<T>("name", ...) and the helper wrappers that take the method name first.
            var callRe = new Regex(@"(?<![\w])(?:Call|Set|CallVoid|CallObject)(?:<([^>]+)>)?\s*\(\s*""(\w+)""");
            foreach (var kv in Sources())
            {
                // Class bodies of the wrapper classes with a known receiver contract: [start, end) -> methods of that contract.
                var scopes = new List<(int start, int end, List<JavaMethod> methods)>();
                foreach (var rc in ReceiverContracts)
                {
                    var cm = Regex.Match(kv.Value, @"\bclass\s+" + rc.Key + @"\b");
                    if (!cm.Success) continue;
                    var methods = new List<JavaMethod>();
                    foreach (var c in rc.Value)
                    {
                        Assert.That(manifest.ContainsKey("com.bugsee.library.contracts." + c), Is.True, c + " is not in the snapshot");
                        AddWithSupers("com.bugsee.library.contracts." + c, manifest, methods);
                    }

                    var open = kv.Value.IndexOf('{', cm.Index);
                    scopes.Add((open, open + ClassBody(kv.Value, cm.Index).Length, methods));
                }

                foreach (Match m in callRe.Matches(kv.Value))
                {
                    seen++;
                    var name = m.Groups[2].Value;
                    var args = SplitArgs(BalancedArgs(kv.Value, m.Index + m.Value.IndexOf('(') + 1)).Skip(1).ToArray();
                    var generic = m.Groups[1].Success ? m.Groups[1].Value.Trim() : null;
                    var scope = scopes.Where(sc => m.Index > sc.start && m.Index < sc.end).Select(sc => sc.methods).FirstOrDefault();
                    if (scope != null) scoped++;
                    var candidates = scope ?? allSdk;
                    var inSdk = candidates.Any(j => j.Name == name
                        && (j.VarArgs ? args.Length >= j.Params.Length - 1 : j.Params.Length == args.Length)
                        && (generic == null || ReturnFits(j, generic)));
                    // Inside a receiver-contract class only the contract counts, except for the JDK objects that class is known to
                    // call (ScopedJdkCalls: the stream of an attachment, the maps and iterators of a report).
                    var inJdk = JdkMethods.TryGetValue(name, out var arities) && arities.Contains(args.Length)
                        && (scope == null || ScopedJdkCalls.Contains(Path.GetFileName(kv.Key) + ":" + name));
                    if (!inSdk && !inJdk)
                        failures.Add(Path.GetFileName(kv.Key) + ": " + name + "/" + args.Length + (scope != null ? " (not on the receiver contract)" : ""));
                }
            }

            Assert.That(seen, Is.GreaterThanOrEqualTo(80));
            Assert.That(scoped, Is.GreaterThanOrEqualTo(60), "the receiver scopes matched too few calls");
            Assert.That(failures, Is.Empty, "Instance calls with no such method and argument count on the receiver contract, the SDK snapshot or the JDK list");
        }

        [Test]
        public void Every_AndroidJavaProxy_implements_an_sdk_or_jdk_interface_with_the_signatures_it_defines()
        {
            var manifest = Manifest();
            var proxies = Proxies(Sources());
            Assert.That(proxies.Count, Is.GreaterThanOrEqualTo(6));
            var failures = new List<string>();
            foreach (var proxy in proxies.Values)
            {
                // Methods of the interface and of the interfaces it extends.
                var known = new List<JavaMethod>();
                if (proxy.Interface == "java.lang.Runnable") known.Add(new JavaMethod { Name = "run", Params = new string[0], Ret = "void" });
                else if (manifest.ContainsKey(proxy.Interface)) AddWithSupers(proxy.Interface, manifest, known);
                else failures.Add(proxy.Name + ": interface " + proxy.Interface + " is not in the snapshot");
                if (known.Count == 0) continue;

                // Public instance methods with a Java-style (lower camel) name are the ones Unity matches against the interface
                // by name and argument types; PascalCase ones (SetFilter, ...) are the C# side's own API. A C# method returning
                // something other than void, or taking a type the Java parameter cannot be, is not found by Unity.
                var defined = Regex.Matches(proxy.Body, @"\bpublic\s+(?!override\b|static\b)([\w<>\[\]?.]+)\s+(\w+)\s*\(([^)]*)\)\s*(?:\{|=>)");
                var matched = 0;
                foreach (var d in defined.Cast<Match>().Where(d => char.IsLower(d.Groups[2].Value[0])))
                {
                    matched++;
                    var name = d.Groups[2].Value;
                    var csParams = SplitParams(d.Groups[3].Value).Select(CsParamTypeOf).ToArray();
                    var ok = known.Any(j => j.Name == name && j.Params.Length == csParams.Length && j.Ret == "void" && d.Groups[1].Value == "void"
                        && csParams.Select((t, i) => CsTypePredicate(t, proxies, manifest)?.Invoke(j.Params[i]) ?? true).All(x => x));
                    if (!ok)
                        failures.Add(proxy.Name + "." + d.Groups[1].Value + " " + name + "(" + string.Join(", ", csParams) + ") does not implement "
                                     + proxy.Interface + ": " + string.Join(" | ", known.Where(j => j.Name == name)));
                }

                Assert.That(matched, Is.GreaterThanOrEqualTo(1), proxy.Name + " defines no method of " + proxy.Interface);

                // The other direction: Unity dispatches by name and argument count when Java calls, so an abstract method the proxy does
                // not define fails only then ("No such proxy method"). Every abstract method of the interface needs a definition.
                var definedKeys = new HashSet<string>(defined.Cast<Match>().Select(d => d.Groups[2].Value + "/" + SplitParams(d.Groups[3].Value).Length));
                foreach (var j in known.Where(j => j.Abstract || proxy.Interface == "java.lang.Runnable"))
                    if (!definedKeys.Contains(j.Name + "/" + j.Params.Length) && !UnimplementedProxyMethods.Contains(proxy.Name + "." + j.Name))
                        failures.Add(proxy.Name + " does not define " + proxy.Interface + "." + j);
            }

            Assert.That(failures, Is.Empty);
        }

        // Interface methods a proxy deliberately leaves out ("Proxy.method"); the Java side never calls them on this object.
        static readonly HashSet<string> UnimplementedProxyMethods = new HashSet<string>();

        static string CsParamTypeOf(string parameter) => Regex.Match(parameter.Trim(), @"^(.+?)\s+\w+(?:\s*=.*)?$").Groups[1].Value;


        [Test]
        public void Every_SpanStatus_constant_the_wrapper_reads_is_a_static_field_of_the_sdk_enum()
        {
            // AndroidSpanHandle reads the constant by name (GetStatic<AndroidJavaObject>(SpanPolicy.AndroidStatusName(status))).
            var fields = Manifest()["com.bugsee.library.contracts.performance.SpanStatus"].Fields;
            foreach (Contracts.Apm.SpanStatus status in Enum.GetValues(typeof(Contracts.Apm.SpanStatus)))
            {
                var name = SpanPolicy.AndroidStatusName(status);
                Assert.That(fields.TryGetValue(name, out var field) && field.isStatic && field.type == "com.bugsee.library.contracts.performance.SpanStatus",
                    Is.True, status + " -> " + name + " is not a static SpanStatus constant in the snapshot");
            }
        }

        // ---- raw JNI (AndroidJNI.GetMethodID & co.) in the frame capturer ----------------------------------------------------

        // Classes the raw JNI code uses that are not in the snapshot on purpose: internal (not contracts), so the snapshot
        // leaves them out. Each is a "this can break silently" risk the device frame-capture scenarios cover.
        static readonly HashSet<string> RawJniNotInSnapshot = new HashSet<string> { "com.bugsee.library.shared.util.TimeUtils" };

        /// <summary>A C# string expression made of literals, const identifiers and "+" (the forms the JNI code uses); null if it is anything else.</summary>
        static string EvalString(string expr, string src)
        {
            var sb = new System.Text.StringBuilder();
            foreach (var part in expr.Split('+'))
            {
                var t = part.Trim();
                var literal = Regex.Match(t, "^\"([^\"]*)\"$");
                if (literal.Success) { sb.Append(literal.Groups[1].Value); continue; }
                var constant = Regex.Match(src, @"\bconst\s+string\s+" + Regex.Escape(t) + @"\s*=\s*((?:""[^""]*""|[^;""])+);");
                if (!constant.Success) return null; // a parameter or a computed value
                var inner = EvalString(constant.Groups[1].Value, src);
                if (inner == null) return null;
                sb.Append(inner);
            }

            return sb.ToString();
        }

        /// <summary>The java types of a JNI descriptor "(...)R", dotted and with "[]" for arrays.</summary>
        static (string[] args, string ret) ParseDescriptor(string descriptor)
        {
            var m = Regex.Match(descriptor, @"^\((.*)\)(.+)$");
            Assert.That(m.Success, Is.True, "bad JNI descriptor " + descriptor);
            string One(Match t)
            {
                var v = t.Value.TrimStart('[');
                var dims = t.Value.Length - v.Length;
                string name;
                switch (v[0])
                {
                    case 'Z': name = "boolean"; break;
                    case 'B': name = "byte"; break;
                    case 'C': name = "char"; break;
                    case 'S': name = "short"; break;
                    case 'I': name = "int"; break;
                    case 'J': name = "long"; break;
                    case 'F': name = "float"; break;
                    case 'D': name = "double"; break;
                    case 'V': name = "void"; break;
                    default: name = v.Substring(1, v.Length - 2).Replace('/', '.'); break;
                }

                return name + string.Concat(Enumerable.Repeat("[]", dims));
            }

            var re = new Regex(@"\[*(?:[ZBCSIJFDV]|L[^;]+;)");
            return (re.Matches(m.Groups[1].Value).Cast<Match>().Select(One).ToArray(), One(re.Match(m.Groups[2].Value)));
        }

        [Test]
        public void Raw_JNI_lookups_in_the_runtime_match_the_snapshot()
        {
            var manifest = Manifest();
            var failures = new List<string>();
            var checkedCount = 0;
            foreach (var path in Directory.GetFiles(RepoFile("Runtime"), "*.cs", SearchOption.AllDirectories))
            {
                var src = StripComments(File.ReadAllText(path));
                if (!src.Contains("AndroidJNI.")) continue;
                var file = Path.GetFileName(path);
                // IntPtr x = FindClassOrClear(<class expr>): the class a later lookup on x is made on.
                var classes = Regex.Matches(src, @"IntPtr\s+(\w+)\s*=\s*(?:FindClassOrClear|AndroidJNI\.FindClass)\(\s*((?:""[^""]*""|[^;""])+?)\s*\)\s*;")
                    .Cast<Match>().Select(m => (var: m.Groups[1].Value, index: m.Index, cls: EvalString(m.Groups[2].Value, src)?.Replace('/', '.')))
                    .Where(c => c.cls != null).ToList();
                foreach (Match m in Regex.Matches(src, @"AndroidJNI\.(GetStaticMethodID|GetMethodID|GetStaticFieldID|GetFieldID)\("))
                {
                    var args = SplitArgs(BalancedArgs(src, m.Index + m.Length));
                    var holder = classes.Where(c => c.var == args[0].Trim() && c.index < m.Index).Select(c => ((string, int, string)?)c).LastOrDefault();
                    if (holder == null || !holder.Value.Item3.StartsWith("com.bugsee.library.")) continue; // Android / Unity classes
                    var cls = holder.Value.Item3;
                    if (RawJniNotInSnapshot.Contains(cls)) continue;
                    // The member name is a literal here, or the parameter a caller fills with a literal (RowOrderConstant("TOP_DOWN")).
                    var nameArg = args[1].Trim();
                    List<string> names;
                    if (Regex.IsMatch(nameArg, "^\"[^\"]+\"$")) names = new List<string> { nameArg.Trim('"') };
                    else
                    {
                        var owner = Regex.Matches(src.Substring(0, m.Index), @"\b(\w+)\s*\(\s*string\s+" + Regex.Escape(nameArg) + @"\s*\)").Cast<Match>().LastOrDefault();
                        Assert.That(owner, Is.Not.Null, file + ": JNI member name '" + nameArg + "' is neither a literal nor a string parameter");
                        names = Regex.Matches(src, @"\b" + owner.Groups[1].Value + @"\(\s*""(\w+)""\s*\)").Cast<Match>().Select(x => x.Groups[1].Value).Distinct().ToList();
                        Assert.That(names, Is.Not.Empty, file + ": no literal caller of " + owner.Groups[1].Value);
                    }

                    if (!manifest.TryGetValue(cls, out var jc))
                    {
                        failures.Add(file + ": " + cls + " is not in the snapshot");
                        continue;
                    }

                    var descriptor = EvalString(args[2], src);
                    Assert.That(descriptor, Is.Not.Null, file + ": cannot evaluate the JNI descriptor " + args[2]);
                    foreach (var name in names)
                    {
                        checkedCount++;
                        if (m.Groups[1].Value.EndsWith("FieldID"))
                        {
                            var (_, fieldType) = ParseDescriptor("()" + descriptor);
                            var isStaticField = m.Groups[1].Value.StartsWith("GetStatic");
                            if (!jc.Fields.TryGetValue(name, out var field) || field.type != fieldType || field.isStatic != isStaticField)
                                failures.Add(file + ": " + (isStaticField ? "static " : "") + cls + "." + name + " : " + descriptor + " is not in the snapshot"
                                             + (jc.Fields.TryGetValue(name, out field) ? "; has " + (field.isStatic ? "static " : "") + field.type : "; no such field"));
                            continue;
                        }

                        var (jArgs, jRet) = ParseDescriptor(descriptor);
                        var isStatic = m.Groups[1].Value.StartsWith("GetStatic");
                        if (!jc.Methods.Any(j => j.Name == name && j.Static == isStatic && j.Ret == jRet && j.Params.SequenceEqual(jArgs)))
                            failures.Add(file + ": " + (isStatic ? "static " : "") + cls + "." + name + descriptor + " is not in the snapshot; has "
                                         + string.Join(" | ", jc.Methods.Where(j => j.Name == name)));
                    }
                }
            }

            Assert.That(checkedCount, Is.GreaterThanOrEqualTo(5), "the raw JNI parser found too few lookups");
            Assert.That(failures, Is.Empty, "Raw JNI lookups the pinned Android SDK does not have");
        }

        [Test]
        public void Snapshot_matches_the_pinned_version()
        {
            var header = File.ReadLines(ManifestFile()).First();
            var version = Regex.Match(File.ReadAllText(RepoFile("Tools~/versions.env")), "ANDROID_SDK_VERSION=\"([^\"]+)\"").Groups[1].Value;
            Assert.That(header, Does.Contain(" " + version + " "));
        }
    }
